import{_ as i,C as o,o as r,c as l,j as a,a as n,E as d,a6 as s}from"./chunks/framework.DIp0zHSV.js";const c="/dev/releases/2026.06.16.1/layout-view-editor.webp",h="/dev/releases/2026.06.16.1/layout-studio.webp",u="/dev/releases/2026.06.16.1/shell-dashboard.webm",p="/dev/releases/2026.06.16.1/elbow-arc-editor.webp",E=JSON.parse('{"title":"LCARdS 2026.06.16.1","description":"Layout view and layout card, shell dashboard preview, state classification, elbow arc modes.","frontmatter":{"version":"2026.06.16.1","date":"2026-06-17T00:00:00.000Z","status":"released","summary":"Layout view and layout card, shell dashboard preview, state classification, elbow arc modes.","breaking":false},"headers":[],"relativePath":"releases/2026.06.16.1.md","filePath":"releases/2026.06.16.1.md","lastUpdated":1791928403000}'),g={name:"releases/2026.06.16.1.md"};function m(y,e,k,f,b,w){const t=o("ReleaseMeta");return r(),l("div",null,[e[0]||(e[0]=a("h1",{id:"lcards-2026-06-16-1",tabindex:"-1"},[n("LCARdS 2026.06.16.1 "),a("a",{class:"header-anchor",href:"#lcards-2026-06-16-1","aria-label":'Permalink to "LCARdS 2026.06.16.1"'},"​")],-1)),d(t),e[1]||(e[1]=s('<p>A larger release with some new structural features to assist in creating dashboards, as well as some important fixes (keep those issues coming!)</p><p>It&#39;s early days for these two new layout features, you will likely find bugs or tweaks needed - please report them in an issue if you do!</p><h2 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h2><h2 id="lcards-dashboard-layout-view-lcards-layout-view" tabindex="-1">LCARdS Dashboard Layout View <a href="/dev/cards/layout-view/"><code>(lcards-layout-view)</code></a> <a class="header-anchor" href="#lcards-dashboard-layout-view-lcards-layout-view" aria-label="Permalink to &quot;LCARdS Dashboard Layout View [`(lcards-layout-view)`](/cards/layout-view/)&quot;">​</a></h2><p>A new Lovelace <strong>view type</strong> (<code>custom:lcards-layout-view</code>), inspired by <a href="https://github.com/thomasloven/lovelace-layout-card" target="_blank" rel="noreferrer"><code>lovelace-custom-layout</code></a> (which I use heavily throughout my system) This view renders a fully configurable CSS Grid and provides a built-in WYSIWYG grid editor directly on the dashboard.</p><img class="release-shot" alt="Layout view grid editor on a dashboard" src="'+c+'"><p><strong>Layout editing:</strong></p><ul><li>Add, resize, reorder, and delete rows and columns directly on the live grid</li><li>Draw, rename, and delete named grid areas by painting cells</li><li>Set gap, grid height, margins, and overflow per view</li><li>Responsive <code>mediaquery</code> grid overrides that switch layouts at specific breakpoints</li></ul><p><strong>Card placement:</strong></p><ul><li>Cards are assigned to a named area via <code>view_layout.grid-area</code>: the editor injects this automatically on add</li><li>Placement controls per card: alignment, margin, and overflow: set inline without leaving the dashboard</li><li>Full support for HA&#39;s native card <strong>Visibility</strong> conditions (delegated to <code>hui-card</code>)</li></ul><p><strong>Per-area surfaces</strong> (<code>layout.areas</code>: LCARdS extension):</p><p>Areas are first-class card-independent styled surfaces. Configurable settings to style background colours, background image, borders, and other CSS properties for card placements.</p><p><strong>Schema compatibility:</strong> The <code>layout</code> block is intentionally compatible with <code>lovelace-layout-card</code>&#39;s <code>custom:grid-layout</code> schema, making it possible to transition existing configurations. Per-area surfaces and the in-view editor are LCARdS-only extensions.</p><hr><h3 id="lcards-layout-card-lcards-layout-card" tabindex="-1">LCARdS Layout Card <a href="/dev/cards/layout-view/#layout-card">(<code>lcards-layout-card</code>)</a> <a class="header-anchor" href="#lcards-layout-card-lcards-layout-card" aria-label="Permalink to &quot;LCARdS Layout Card [(`lcards-layout-card`)](/cards/layout-view/#layout-card)&quot;">​</a></h3><p>The card version of the LCARdS layout view: (<code>custom:lcards-layout-card</code>) embeds the same customizable CSS Grid inside any area of <code>lcards-layout-view</code> (or any other card container or dashboard.)<br> It shares the same layout schema as the view, so the same configuration patterns and per-area surface settings apply at the card level.</p><p>Like the WYSIWYG editing of the dashboard version, the card ships with <strong>Layout Studio</strong>: a full editor dialog accessible from the card&#39;s editor panel</p><img class="release-shot" alt="Layout Studio dialog for the layout card" src="'+h+'"><hr><h3 id="lcards-shell-dashboard-preview" tabindex="-1">LCARdS Shell Dashboard (Preview) <a class="header-anchor" href="#lcards-shell-dashboard-preview" aria-label="Permalink to &quot;LCARdS Shell Dashboard (Preview)&quot;">​</a></h3>',20)),e[2]||(e[2]=a("p",null,[a("video",{class:"release-shot",src:u,title:"LCARdS shell dashboard preview",autoplay:"",loop:"",muted:"",playsinline:""})],-1)),e[3]||(e[3]=s(`<p>Included is a new dashboard strategy (<code>custom:lcards-shell-strategy</code>) which registers in HA&#39;s <strong>New Dashboard</strong> picker.<br> This dashboard is built on the new LCARdS layout dashboard view <code>lcards-layout-view</code> and card <code>lcards-layout-card</code>. It serves as an example of how to put these to use in a real dashboard scenario.</p><p>The shell includes a collapsible top header bar, a left sidebar with page navigation, a dynamic room selector, and a right sidebar, all wired to helper entities you configure in the strategy&#39;s setup dialog:</p><blockquote><p><strong>Preview note:</strong> The Shell Strategy is a proof-of-concept and testing vehicle for the layout primitives. It requires <a href="https://github.com/thomasloven/lovelace-auto-entities" target="_blank" rel="noreferrer"><code>auto-entities</code></a> (HACS) for the dynamic room light list. <br> Edit the dashboard and <code>Take Control</code> to get access to the full underlying YAML that was generated.</p></blockquote><h2 id="custom-state-bucket-mapping-state-classification" tabindex="-1">Custom State Bucket Mapping <a href="/dev/core/colours.html#custom-state-classification-state-classification"><code>(state_classification)</code></a> <a class="header-anchor" href="#custom-state-bucket-mapping-state-classification" aria-label="Permalink to &quot;Custom State Bucket Mapping [\`(state_classification)\`](/core/colours#custom-state-classification-state-classification)&quot;">​</a></h2><p>Cards that use state-based colours (<code>lcards-button</code>, <code>lcards-elbow</code>, <code>lcards-slider</code>) now support a top-level <code>state_classification</code> key that controls how raw entity states map into the buckets like <code>active</code> / <code>inactive</code> / <code>default</code> or any other custom style bucket you create. You can also direct which bucket catches any fall-through values.</p><p>For example, when a person is at a custom zone, the entity state is the zone name (e.g. <code>&quot;work&quot;</code>, <code>&quot;downtown&quot;</code>). Before, all such zone names fell into the <code>inactive</code> bucket (the person is not <code>home</code> so it was considered <code>inactive</code> where you would maybe expect it to fall through to the default bucket.) Now, you can direct these via the <code>else:</code> key within <code>state_classification</code>.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom:lcards-button</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">entity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">person.jay</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">state_classification</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">default</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # unmapped zone names → &quot;default&quot; bucket</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  card</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      background</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        home</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">var(--lcars-green)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        not_home</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">var(--lcars-mango)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">var(--lcars-blue)</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # custom zones not explicitly defined now land here</span></span></code></pre></div><p>You can now also override builtin bucket values, or create your own buckets. Please see the <a href="/dev/core/colours.html#custom-state-classification-state-classification"><code>(documentation)</code></a> for details.</p><h2 id="elbow-arc-radius-modes-editor-overhaul-fix-361" tabindex="-1">Elbow: Arc Radius Modes &amp; Editor Overhaul (fix <a href="https://github.com/snootched/lcards/issues/361" target="_blank" rel="noreferrer">#361</a>) <a class="header-anchor" href="#elbow-arc-radius-modes-editor-overhaul-fix-361" aria-label="Permalink to &quot;Elbow: Arc Radius Modes &amp; Editor Overhaul (fix [#361](https://github.com/snootched/lcards/issues/361))&quot;">​</a></h2><p>The <code>lcards-elbow</code> card has been uplifted with many improvements for the control of overall elbow style, and the editing UX.</p><ul><li>config fields for arcs now accept <strong>keyword modes</strong> in addition to raw pixel values. Giving full control on how the arcs are derived from the shape of the card and the elbow arms.</li><li>Clamping mode of the arcs is configurable. You can now override the default camp protection that would recalculate arcs when they would not fit within the card&#39;s dimensions.</li><li>Full card editor uplift for elbow arcs: <ul><li>reorganized sections for settings</li><li>live preview showing how the selected settings drive arc calculations, and show before/after values if clamping was applied.</li></ul></li><li><strong>Reference diagram</strong> updated for clarity</li></ul><img class="release-shot" alt="Elbow arc settings with live preview" src="`+p+'"><h2 id="enhancements-fixes" tabindex="-1">Enhancements &amp; Fixes <a class="header-anchor" href="#enhancements-fixes" aria-label="Permalink to &quot;Enhancements &amp; Fixes&quot;">​</a></h2><ul><li><strong>Position Names Canonicalized (fix <a href="https://github.com/snootched/lcards/issues/367" target="_blank" rel="noreferrer">#367</a>)</strong>: The 9-point position system used throughout now uses consistent hyphenated names everywhere: <code>center-left</code> and <code>center-right</code>. Internal alias normalizer handles any existing configs automatically: no YAML changes required.</li><li><strong>Animation Lifecycle Fix (TriggerManager Lifecycle Guard) (fix <a href="https://github.com/snootched/lcards/issues/365" target="_blank" rel="noreferrer">#365</a>)</strong>: animations will now properly stop when using <code>on_entity_change</code> <code>while</code> etc.</li><li><code>lcards-select-menu</code> now accepts explicit height configuration alongside its existing grid layout options, giving more precise control when using the select menu in fixed-height grid areas.</li><li><strong>Font Asset autoload</strong>: fixed font autoloading issue. Font definitions now support an <code>autoLoad</code> property in the AssetManager. When set, the font is loaded automatically at LCARdS initialization without requiring explicit activation. Core fonts like Antonio have been autoloaded at startup in case they are not available via HA theme.</li><li><strong>CI: CSS Variable Deprecation Warnings</strong>: Build-time CSS variable validator (which runs as part of <code>npm run build</code>) now reports <strong>deprecation warnings</strong> for any <code>--lcars-*</code> or <code>--lcards-*</code> variables that have been renamed or removed from the upstream themes.</li></ul><hr><p>All changes: <a href="https://github.com/snootched/lcards/compare/2026.06.01.1...2026.06.16.1" target="_blank" rel="noreferrer">2026.06.01.1...2026.06.16.1</a></p>',16))])}const _=i(g,[["render",m]]);export{E as __pageData,_ as default};
